8.6 Comparación de Diagramas de Persistencia entre Países
¿La topología de la red de un país difiere de la de otro? Uno pensaría que conociendo las estructuras topológicas de los grafos de coocurrencia de cada país podríamos compararlas directamente y obtener conclusiones sobre la similitud ecológica entre los países. En TDA, la distancia de Wasserstein es una métrica que nos permite comparar diagramas de persistencia y cuantificar la diferencia entre ellos. Esta distancia se calcula como el costo mínimo de transformar un diagrama de persistencia en otro, considerando tanto la posición de los puntos como su multiplicidad.

La distancia de Wasserstein compara diagramas de persistencia; no mide directamente similitud ecológica. Usamos solo puntos con muerte finita (en \(H_0\) existe una componente esencial con muerte infinita). Comparamos únicamente países con el mismo conjunto de géneros y la misma transformación de correlación. Las distancias calculadas son descriptivas y no constituyen pruebas de significación. Con pocos datos, incluso estas comparaciones pueden ser muy inestables.



Código
from gudhi.hera import wasserstein_distance

# South Africa se analiza en el ejemplo principal. Los demás países solo se
# incorporan si el estudiante los agrega a countries_to_process.
country_persistence = {}
if "persistence_south_africa_by_type" in globals():
    country_persistence["South Africa"] = {
        distance_type: result[0]
        for distance_type, result in persistence_south_africa_by_type.items()
    }

for country_name, result in correlation_results_by_country.items():
    country_persistence[country_name] = {
        distance_type: persistence_result[0]
        for distance_type, persistence_result in result["persistence"].items()
    }

country_names = sorted(country_persistence)
if len(country_names) &lt; 2:
    print(
        "La distancia de Wasserstein requiere al menos dos países. "
        "Agrega países a countries_to_process y vuelve a ejecutar las celdas "
        "de análisis antes de esta comparación."
    )
else:
    correlation_types = ["absolute", "positive", "negative"]
    homology_dimensions = [0, 1, 2]
    wasserstein_matrices = {}

    for correlation_type in correlation_types:
        for dimension in homology_dimensions:
            distance_matrix = pd.DataFrame(
                0.0,
                index=country_names,
                columns=country_names
            )
            diagrams = {}
            for country_name in country_names:
                diagram = country_persistence[country_name][correlation_type]
                finite_points = [
                    point for dim, point in diagram
                    if dim == dimension and np.isfinite(point).all()
                ]
                diagrams[country_name] = np.asarray(
                    finite_points, dtype=float
                ).reshape(-1, 2)

            for i, country_a in enumerate(country_names):
                for country_b in country_names[i + 1:]:
                    diagram_a = diagrams[country_a]
                    diagram_b = diagrams[country_b]
                    if len(diagram_a) == 0 and len(diagram_b) == 0:
                        distance = 0.0
                    else:
                        distance = wasserstein_distance(
                            diagram_a, diagram_b, order=2
                        )
                    distance_matrix.loc[country_a, country_b] = distance
                    distance_matrix.loc[country_b, country_a] = distance

            wasserstein_matrices[(correlation_type, dimension)] = distance_matrix

    wasserstein_output_dir = os.path.join(
        corr_output_dir, "Wasserstein", "Tomato_top10"
    )
    os.makedirs(wasserstein_output_dir, exist_ok=True)

    for correlation_type in correlation_types:
        fig, axes = plt.subplots(
            1, len(homology_dimensions), figsize=(16, 5), constrained_layout=True
        )
        max_distance = max(
            wasserstein_matrices[(correlation_type, dimension)].to_numpy().max()
            for dimension in homology_dimensions
        )
        vmax = max_distance if max_distance &gt; 0 else 1.0

        for ax, dimension in zip(axes, homology_dimensions):
            matrix = wasserstein_matrices[(correlation_type, dimension)]
            matrix.to_csv(
                os.path.join(
                    wasserstein_output_dir,
                    f"wasserstein_{correlation_type}_dimension_{dimension}.csv"
                )
            )
            sns.heatmap(
                matrix,
                annot=True,
                fmt=".3f",
                cmap="viridis",
                vmin=0,
                vmax=vmax,
                square=True,
                ax=ax,
                cbar=ax is axes[-1]
            )
            ax.set_title(f"Homology dimension {dimension}")
            ax.set_xlabel("Country")
            ax.set_ylabel("Country")

        fig.suptitle(
            f"Wasserstein distances: {correlation_type} Spearman distances"
        )
        figure_path = os.path.join(
            wasserstein_output_dir,
            f"wasserstein_{correlation_type}_top10.jpg"
        )
        fig.savefig(figure_path, bbox_inches="tight", dpi=180)
        plt.show()
        plt.close(fig)
        print(f"{correlation_type}: saved heatmap to {figure_path}")

    print(f"Countries compared: {country_names}")
    print(f"Wasserstein matrices saved to: {wasserstein_output_dir}")
